import SettingsView, { LanguageSelect } from './SettingsView';
import { t, message as systemMessage, locale, useLanguage } from './i18n';
import { SecureImage, SecureLink } from './SecureResources';
import { api, post } from './client';
import { InboxView, LibraryView, VersionAnnotation } from './Library';
import BackupView from './BackupView';
import OfflineView from './OfflineView';
import CompareView from './CompareView';
import TimelineView, { DiagnosticsPanel, ObservationList, QualitySummary, useObservations, type ArchiveVersion, type Observation, type HistorySummary, type Diagnostic } from './TimelineView';
import ArchiveReview from './ArchiveReview';
import LandingLifecycle from './LandingLifecycle';
import RuleEditor, { type MonitoringRule } from './RuleEditor';
import { useCallback, useEffect, useRef, useState } from 'react';
import type { FormEvent, ReactNode } from 'react';
import { ArrowDownToLine, ArrowLeft, ArrowRight, ArrowUpRight, Check, ChevronRight, Clock3, ExternalLink, FileText, FolderArchive, Globe2, History, LayoutDashboard, Link2, LoaderCircle, LockKeyhole, LogOut, Menu, MessageSquare, Monitor, Pause, Play, Plus, RefreshCw, Search, Settings2, ShieldCheck, Sparkles, Trash2, X } from 'lucide-react';

type Site = { id: string; name: string; url: string; kind: 'own' | 'competitor'; intervalHours: number; discoveryIntervalHours: number; nextDiscoveryAt?: string; lastDiscoveryAt?: string; includePaths: string[]; excludePaths: string[]; maxPages: number; includeSubdomains: boolean; paused: boolean; pageCount: number; versionCount: number; lastCheckedAt?: string; nextCheckAt?: string; ignoreSelectors: string[]; notes?: string };
type Page = { source: string; firstSeenAt?: string; lastSuccessfulAt?: string; lifecycle: 'new' | 'changed' | 'missing' | 'recovered'; sitemapState: string; sitemapSeenAt?: string; ignoreRules: MonitoringRule[]; importantRules: MonitoringRule[]; id: string; url: string; title: string; lastCheckedAt?: string; lastStatus?: string; versionCount: number; latestVersionId?: string; latestCheckId?: string; lastChangeAt?: string; referenceVersionId?: string | null; pendingConfirmation?: { count: number; retries: number; firstSeenAt: string } | null };
type Version = ArchiveVersion;
type Event = { id: string; kind: string; url: string; siteName: string; createdAt: string; message: string };
type Job = { id: string; siteId: string; pageId?: string; kind: string; status: string; manual: number; paused: number; attempts: number; error?: string; url: string; siteName: string; createdAt: string; startedAt?: string; availableAt: string };
type Dashboard = { version: string; stats: { sites: number; pages: number; versions: number; bytes: number; queued: number; running: number }; events: Event[]; storage: { freeBytes: number; totalBytes: number; minFreeBytes: number }; worker: { available: boolean; message?: string; schedulerEnabled: boolean; version?: string; expectedVersion?: string; compatible?: boolean }; diagnosticsStatus?: { bytes: number; maxBytes: number; retentionHours: number; count: number }; queue: Job[] };
type SiteDetail = { site: Site; pages: Page[]; events: Event[]; jobs: Job[] };
type PageDetail = { page: Page; site: Site; jobs: Job[]; versions: Version[]; checks: Observation[]; notes: string; referenceVersionId?: string | null; historySummary?: HistorySummary; diagnostics?: Diagnostic[] };
type Route = { view: 'overview' | 'sites' | 'site' | 'page' | 'inbox' | 'library' | 'backup' | 'settings'; id?: string; versionId?: string };
type AuthStatus = { setupRequired: boolean; authenticated: boolean };

const date = (value?: string, short = false) => value ? new Intl.DateTimeFormat(locale(), { day: '2-digit', month: 'short', ...(short ? {} : { year: 'numeric' }), hour: '2-digit', minute: '2-digit' }).format(new Date(value)) : '—';
const bytes = (value?: number) => { if (value === undefined || value === null || !Number.isFinite(value)) return '—'; if (!value) return '0 B'; const unit = Math.min(Math.floor(Math.log(value) / Math.log(1024)), 4); return `${new Intl.NumberFormat(locale(), { maximumFractionDigits: unit > 1 ? 1 : 0 }).format(value / 1024 ** unit)} ${['B', 'KB', 'MB', 'GB', 'TB'][unit]}`; };
const host = (url: string) => { try { return new URL(url).hostname.replace(/^www\./, ''); } catch { return url; } };
const urlPath = (url: string) => { try { const parsed = new URL(url); return parsed.pathname + parsed.search; } catch { return url; } };
const routeFromHash = (): Route => { const [view, id, versionId] = window.location.hash.replace(/^#\/?/, '').split('/'); return ['sites', 'site', 'page', 'inbox', 'library', 'backup', 'settings'].includes(view) ? { view: view as Route['view'], id, versionId } : { view: 'overview' }; };
const go = (view: Route['view'], id?: string) => { window.location.hash = `/${view}${id ? `/${id}` : ''}`; };
const statusLabel = (status?: string) => ({ archive_reset: t("Fresh scan"), observed: t("Evidence saved"), partial: t("Copy needs review"), baseline: t("Rules updated"), quality_restored: t("Copy completed"), sitemap_absent: t("Absent from sitemap"), sitemap_returned: t("Back in sitemap"), ok: t("Archived"), unavailable: t("Needs review"), recovered: t("Back online"), changed: t("Changed"), new: t("First copy"), captured: t("Archived"), unchanged: t("Unchanged"), error: t("Error"), failed: t("Error"), missing: t("Unreachable"), disappeared: t("Unreachable"), removed: t("Unreachable"), restored: t("Back online"), returned: t("Previous version returned"), cancelled: t("Stopped"), queued: t("Queued"), running: t("Running"), succeeded: t("Completed"), success: t("Completed"), blocked: t("Access blocked"), discovered: t("Page discovered"), discovery: t("Page discovery"), capture: t("Capture") }[status || ''] || (status ? t("Checked") : t("Not captured yet")));
const isErrorStatus = (status?: string) => !!status && ['partial', 'error', 'failed', 'unavailable', 'missing', 'disappeared', 'removed', 'blocked'].includes(status);

function Spinner({ label = t("Loading") }: { label?: string }) { return <div className="loading" role="status"><LoaderCircle className="spin" size={22} /><span>{systemMessage(label)}…</span></div>; }
type Action = (fn: () => Promise<unknown>, message: string) => Promise<void>;

function ScanButton({ siteId, pageId, running, perform, compact = false }: { siteId: string; pageId?: string; running: boolean; perform: Action; compact?: boolean }) {
  const [busy, setBusy] = useState(false);
  return <button className={`button ${compact ? 'secondary compact' : 'primary'}`} disabled={busy} onClick={async () => {
    setBusy(true);
    try { await perform(() => post(pageId ? `/api/pages/${pageId}/scan` : `/api/sites/${siteId}/scan`, { force: true, discover: !pageId }), t("Priority manual check requested. Its status will update below.")); }
    finally { setBusy(false); }
  }} title={running ? t("Stop the current attempt and start a new check.") : t("Download the page again even when monitoring is paused. Save a new version when changes are detected.")}>
    {busy ? <LoaderCircle className="spin" size={17} /> : <RefreshCw size={17} />}{busy ? t("Requesting…") : running ? t("Restart check") : compact ? t("Download now") : t("Check and download now")}
  </button>;
}

function AcquisitionStatus({ jobs, paused, error }: { jobs: Job[]; paused: boolean; error?: string }) {
  const running = jobs.find(job => job.status === 'running');
  const queued = jobs.filter(job => job.status === 'queued');
  const next = queued.find(job => !job.paused || job.manual);
  const seconds = running?.startedAt ? Math.max(0, Math.floor((Date.now() - Date.parse(running.startedAt)) / 1000)) : 0;
  return <section className="acquisition-status" aria-label={t("Capture status")} aria-live="polite">
    <div><strong>{running ? t("{p0} running · {p1} seconds", { p0: statusLabel(running.kind), p1: seconds }) : next ? Date.parse(next.availableAt) > Date.now() ? t("Next attempt: {p0}", { p0: date(next.availableAt, true) }) : t("Check ready, waiting for the engine") : paused ? t("Automatic monitoring paused") : t("No capture in progress")}</strong>
      {running && <p>{urlPath(running.url)} {t(" · attempt ")}{running.attempts}{t("/3. Each job can take up to 3 minutes.")}</p>}
      {!!queued.length && <p>{queued.length}{queued.length >= 100 ? '+' : ''} {queued.length === 1 ? t("check queued") : t("checks queued")}{t(". Manual checks take priority.")}</p>}
      <p>{paused ? t("Manual checks also work while paused and do not resume the schedule.") : t("“Check and download now” starts a new visit. If the content is unchanged, the check is recorded without duplicating the version.")}{running && t(" “Restart check” stops the current attempt.")}</p>
    </div>
    {(next?.error || error) && <div className="acquisition-error"><strong>{t("Last recorded error")}</strong><p>{systemMessage(next?.error || error)}</p></div>}
  </section>;
}

function DeleteSiteModal({ site, close, deleted }: { site: Site; close: () => void; deleted: (pendingFiles: number) => Promise<void> }) {
  const [confirmed, setConfirmed] = useState(false); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  return <Modal title={t("Delete site from the archive")} subtitle={site.name} close={() => { if (!busy) close(); }}>
    <form onSubmit={async event => {
      event.preventDefault(); if (!confirmed || busy) return; setBusy(true); setError('');
      try {
        const result = await api<{ pendingFiles: number }>(`/api/sites/${site.id}`, { method: 'DELETE', body: JSON.stringify({ confirmSiteId: site.id }) });
        await deleted(result.pendingFiles);
      } catch (error) { setError((error as Error).message); } finally { setBusy(false); }
    }}><div className="modal-body">
      <p>{t("This will delete ")}<strong>{site.pageCount} {site.pageCount === 1 ? t("page") : t("pages")}</strong>, <strong>{site.versionCount} {site.versionCount === 1 ? t("version") : t("versions")}</strong>{t(", notes and history for this site. Running and scheduled checks will be cancelled.")}</p>
      <p>{t("Files shared with other sites will be kept. This cannot be undone in the app; recovering copies requires an earlier backup.")}</p>
      <SecureLink className="text-button" href="/api/export" download><ArrowDownToLine size={16} /> {t(" Download an archive backup first")}</SecureLink>
      <label className="checkbox-label"><input type="checkbox" checked={confirmed} onChange={event => setConfirmed(event.target.checked)} disabled={busy} /><span>{t("I confirm that I want to delete this site and its archived copies.")}</span></label>
      {error && <div className="notice error" role="alert">{systemMessage(error)}</div>}
    </div><div className="modal-footer"><button type="button" className="button secondary" disabled={busy} onClick={close}>{t("Cancel")}</button><button className="button danger" disabled={!confirmed || busy}>{busy ? <LoaderCircle className="spin" size={17} /> : <Trash2 size={17} />}{busy ? t("Deleting…") : t("Delete permanently")}</button></div></form>
  </Modal>;
}
function ResetSiteModal({ site, close, done }: { site: Site; close: () => void; done: (message: string) => Promise<void> }) {
  type Preview = { token: string; versions: number; pages: number; annotatedVersions: number; reclaimableBytes: number };
  const [preview, setPreview] = useState<Preview>(); const [confirmed, setConfirmed] = useState(false);
  const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  async function load() {
    setPreview(undefined); setConfirmed(false); setError(''); setBusy(true);
    try { setPreview(await api<Preview>(`/api/sites/${site.id}/reset`)); }
    catch (cause) { setError((cause as Error).message); } finally { setBusy(false); }
  }
  useEffect(() => { void load(); }, [site.id]);
  return <Modal title={t("Clear copies and scan again")} subtitle={site.name} close={() => { if (!busy) close(); }}>
    <form onSubmit={async event => {
      event.preventDefault(); if (!preview || !confirmed || busy) return; setBusy(true); setError('');
      try {
        const result = await post<{ message: string; pendingFiles: number }>(`/api/sites/${site.id}/reset`, { token: preview.token, confirmSiteId: site.id });
        await done(result.message + (result.pendingFiles ? t(" Some unshared files could not be removed from disk. Check the data volume permissions.") : ''));
      } catch (cause) { setConfirmed(false); setError((cause as Error).message); } finally { setBusy(false); }
    }}><div className="modal-body">
      {!preview && !error && <p role="status">{t("Preparing preview…")}</p>}
      {preview && <><p>{t("This will delete ")}<strong>{t("all ")}{preview.versions} {t(" copies")}</strong> {t(" for this site, including screenshots, HTML, favorites, tags and notes on individual copies")}{preview.annotatedVersions ? t(" ({p0} annotated or favorite copies)", { p0: preview.annotatedVersions }) : ''}.</p>
        <p>{t("The site, its ")}{preview.pages} {t(" addresses, settings and page notes will be kept. The new scan starts from scratch, without comparing against old copies. Check dates remain recorded with a note that their files were removed.")}</p>
        <p>{t("Reclaimable space: ")}<strong>{bytes(preview.reclaimableBytes)}</strong>{t(". Files shared with other sites remain available. Recovering deleted copies requires an earlier backup; a new scan cannot recreate pages that are no longer online.")}</p>
        <SecureLink className="text-button" href="/api/export" download><ArrowDownToLine size={16} /> {t(" Download an archive backup first")}</SecureLink>
        <label className="checkbox-label"><input type="checkbox" disabled={busy} checked={confirmed} onChange={event => setConfirmed(event.target.checked)} /><span>{t("I confirm that I want to delete all copies of ")}{site.name} {t(" and start a fresh scan.")}</span></label>
      </>}
      {error && <div className="notice error" role="alert">{systemMessage(error)}</div>}
    </div><div className="modal-footer"><button type="button" className="button secondary" disabled={busy} onClick={close}>{t("Cancel")}</button>{error && <button type="button" className="button secondary" disabled={busy} onClick={load}>{t("Refresh preview")}</button>}<button className="button danger" disabled={busy || !preview || !confirmed}>{busy ? <LoaderCircle className="spin" size={17} /> : <RefreshCw size={17} />}{t("Confirm reset and scan")}</button></div></form>
  </Modal>;
}
function Badge({ children, tone = 'neutral' }: { children: ReactNode; tone?: 'neutral' | 'green' | 'amber' }) { return <span className={`badge ${tone}`}>{children}</span>; }
function Empty({ icon, title, children, action }: { icon: ReactNode; title: string; children: ReactNode; action?: ReactNode }) { return <div className="empty"><div className="empty-icon">{icon}</div><h3>{title}</h3><p>{children}</p>{action}</div>; }

export default function App() {
  useLanguage();
  const [auth, setAuth] = useState<AuthStatus | null>(null);
  const [initialError, setInitialError] = useState('');
  useEffect(() => {
    const load = () => api<AuthStatus>('/api/auth/status').then(setAuth).catch(error => setInitialError(error.message));
    load(); window.addEventListener('session-expired', load); return () => window.removeEventListener('session-expired', load);
  }, []);
  if (!auth) return <main className="startup"><Brand />{initialError ? <div className="notice error">{systemMessage(initialError)}<button className="text-button" onClick={() => window.location.reload()}>{t("Retry")}</button></div> : <Spinner label={t("Opening the archive")} />}</main>;
  if (!auth.authenticated) return <AuthScreen setup={auth.setupRequired} onSuccess={() => setAuth({ setupRequired: false, authenticated: true })} />;
  return <Workspace onLogout={async () => { await post('/api/auth/logout'); setAuth({ setupRequired: false, authenticated: false }); }} />;
}

function Brand() { return <div className="brand"><div className="brand-icon"><History size={24} strokeWidth={1.8} /></div><div><strong>Landing Archive</strong><span>{t("Your websites, remembered")}</span></div></div>; }

function AuthScreen({ setup, onSuccess }: { setup: boolean; onSuccess: () => void }) {
  const [username, setUsername] = useState(''); const [password, setPassword] = useState(''); const [confirm, setConfirm] = useState(''); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  async function submit(event: FormEvent) { event.preventDefault(); if (setup && password !== confirm) { setError(t("The passwords do not match.")); return; } setBusy(true); setError(''); try { await post(setup ? '/api/auth/setup' : '/api/auth/login', { username, password }); onSuccess(); } catch (error) { setError((error as Error).message); } finally { setBusy(false); } }
  return <main className="auth-layout"><section className="auth-story"><Brand /><div><span className="eyebrow light">{t("YOUR WEB OBSERVATORY")}</span><h1>{t("Pages change.")}<br />{t("Their history stays.")}</h1><p>{t("Save landing pages, revisit past offers and follow how the websites you track evolve.")}</p><div className="auth-steps"><span><Globe2 size={18} /> {t(" Follow websites")}</span><span><FolderArchive size={18} /> {t(" Keep their versions")}</span><span><History size={18} /> {t(" Explore their history")}</span></div></div><span className="auth-local"><ShieldCheck size={17} /> {t(" Your archive stays on your device.")}</span></section><section className="auth-form-wrap"><LanguageSelect compact /><form className="auth-form" onSubmit={submit}><div className="auth-lock"><LockKeyhole size={23} /></div><span className="eyebrow">{setup ? t("WELCOME TO YOUR ARCHIVE") : t("YOUR PRIVATE SPACE")}</span><h2>{setup ? t("Set up your access.") : t("Welcome back.")}</h2><p>{setup ? t("Create a local account to protect your sites, captures and notes.") : t("Sign in to explore the history of the sites you follow.")}</p><label>{t("Username")}<input autoFocus autoComplete="username" required minLength={3} maxLength={40} value={username} onChange={event => setUsername(event.target.value)} /></label><label>Password<input type="password" autoComplete={setup ? 'new-password' : 'current-password'} required minLength={setup ? 12 : undefined} value={password} onChange={event => setPassword(event.target.value)} />{setup && <small>{t("At least 12 characters. Keep it somewhere safe.")}</small>}</label>{setup && <label>{t("Repeat password")}<input type="password" autoComplete="new-password" required value={confirm} onChange={event => setConfirm(event.target.value)} /></label>}{error && <div className="notice error" role="alert">{systemMessage(error)}</div>}<button className="button primary full" disabled={busy}>{busy ? <LoaderCircle size={18} className="spin" /> : <ArrowRight size={18} />}{setup ? t("Create your archive") : t("Sign in")}</button></form></section></main>;
}

function Workspace({ onLogout }: { onLogout: () => Promise<void> }) {
  const [route, setRoute] = useState<Route>(routeFromHash); const [sites, setSites] = useState<Site[]>([]); const [dashboard, setDashboard] = useState<Dashboard | null>(null); const [detail, setDetail] = useState<SiteDetail | PageDetail | null>(null); const [loading, setLoading] = useState(true); const [error, setError] = useState(''); const [toast, setToast] = useState(''); const [editingSite, setEditingSite] = useState<Site | 'new' | null>(null); const [deletingSite, setDeletingSite] = useState<Site | null>(null); const [mobileNav, setMobileNav] = useState(false); const [search, setSearch] = useState(''); const [results, setResults] = useState<{ id: string; url: string; title: string; siteName: string }[] | null>(null);
  const requestId = useRef(0); const currentRoute = useRef(route); currentRoute.current = route;
  const load = useCallback(async (silent = false) => {
    const id = ++requestId.current;
    if (!silent) setLoading(true);
    try {
      const [siteData, dashboardData, detailData] = await Promise.all([api<{ sites: Site[] }>('/api/sites'), api<Dashboard>('/api/dashboard'), route.id && (route.view === 'site' || route.view === 'page') ? api<SiteDetail | PageDetail>(`/api/${route.view === 'site' ? 'sites' : 'pages'}/${route.id}`) : Promise.resolve(null)]);
      if (id !== requestId.current) return;
      setSites(siteData.sites); setDashboard(dashboardData); setDetail(detailData); setError('');
    } catch (error) { if (id === requestId.current) setError((error as Error).message); }
    finally { if (id === requestId.current) setLoading(false); }
  }, [route.view, route.id, route.versionId]);
  useEffect(() => { const handler = () => { setRoute(routeFromHash()); setDetail(null); setMobileNav(false); setSearch(''); window.scrollTo(0, 0); }; window.addEventListener('hashchange', handler); return () => window.removeEventListener('hashchange', handler); }, []);
  useEffect(() => { load(); }, [load]);
  const activeJobs = (dashboard?.stats.queued || 0) + (dashboard?.stats.running || 0);
  useEffect(() => { const timer = window.setInterval(() => { if (!document.hidden) load(true); }, activeJobs ? 4000 : 30000); return () => clearInterval(timer); }, [load, activeJobs]);
  useEffect(() => { if (!toast) return; const timer = window.setTimeout(() => setToast(''), 5500); return () => clearTimeout(timer); }, [toast]);
  useEffect(() => { if (!search.trim()) { setResults(null); return; } let cancelled = false; const timer = window.setTimeout(() => { api<{ pages: NonNullable<typeof results> }>(`/api/search?q=${encodeURIComponent(search.trim())}`).then(data => { if (!cancelled) setResults(data.pages); }).catch(() => { if (!cancelled) setResults([]); }); }, 250); return () => { cancelled = true; clearTimeout(timer); }; }, [search]);
  const notify = (message: string) => setToast(message);
  const perform = async (fn: () => Promise<unknown>, message: string) => { try { await fn(); notify(message); await load(true); } catch (error) { setError((error as Error).message); } };
  const selectedSite = detail?.site || null;
  const deleted = async (pendingFiles: number) => {
    ++requestId.current; setDeletingSite(null); setDetail(null); setError(''); setSearch(''); setResults(null);
    notify(pendingFiles ? t("Site deleted. Some files could not be removed from disk. Check the data volume permissions.") : t("Site and archive deleted. Files shared with other sites have been kept."));
    if (currentRoute.current.view === 'sites') await load(true); else go('sites');
  };
  return <div className="app-shell"><aside className={`sidebar ${mobileNav ? 'open' : ''}`}><a className="brand-link" href="#/overview"><Brand /></a><div className="sidebar-label">{t("YOUR ARCHIVE")}</div><nav aria-label={t("Main navigation")}><a href="#/overview" className={`nav-item ${route.view === 'overview' ? 'active' : ''}`}><LayoutDashboard size={19} /> {t(" Overview")}</a><a href="#/sites" className={`nav-item ${['sites','site','page'].includes(route.view) ? 'active' : ''}`}><Globe2 size={19} /> {t(" Monitored sites ")}<span>{sites.length}</span></a><a href="#/inbox" className={`nav-item ${route.view === 'inbox' ? 'active' : ''}`}><Sparkles size={19} /> {t(" Updates")}</a><a href="#/library" className={`nav-item ${route.view === 'library' ? 'active' : ''}`}><MessageSquare size={19} /> {t(" Collection")}</a></nav><div className="sidebar-label sites-label">{t("RECENT SITES ")}<button className="icon-button" aria-label={t("Add site")} onClick={() => setEditingSite('new')}><Plus size={17} /></button></div><div className="sidebar-sites">{sites.slice(0, 8).map(site => <a key={site.id} href={`#/site/${site.id}`} className={`sidebar-site ${selectedSite?.id === site.id ? 'selected' : ''}`}><span className={`site-dot ${site.paused ? 'paused' : ''}`} /><span>{site.name}</span>{site.kind === 'own' && <span className="own-dot" title={t("One of your sites")} />}</a>)}{!sites.length && <p className="sidebar-hint">{t("Sites you add will appear here.")}</p>}</div><div className="sidebar-bottom"><div className="local-status"><ShieldCheck size={19} /><div><strong>{t("Local archive")}</strong><span>{t("Your data, on your device")}</span></div></div><a className={`nav-item subdued ${route.view === 'settings' ? 'active' : ''}`} href="#/settings"><Settings2 size={18} /> {t("Settings")}</a><a className="nav-item subdued" href="#/backup"><FolderArchive size={18} /> {t(" Backup and restore")}</a><button className="nav-item subdued" onClick={() => perform(onLogout, '')}><LogOut size={18} /> {t(" Sign out")}</button><div className="sidebar-version">LANDING ARCHIVE <span>v{dashboard?.version || "…"}</span></div></div></aside>{mobileNav && <button className="nav-scrim" aria-label={t("Close navigation")} onClick={() => setMobileNav(false)} />}
    <div className="workspace"><header className="topbar"><button className="icon-button mobile-toggle" aria-label={t("Open navigation")} onClick={() => setMobileNav(!mobileNav)}><Menu size={23} /></button><div className="breadcrumb"><span>{t("Archive")}</span><ChevronRight size={14} /><strong>{route.view === 'overview' ? t("Overview") : route.view === 'sites' ? t("Monitored sites") : route.view === 'inbox' ? t("Updates") : route.view === 'library' ? t("Collection") : route.view === 'settings' ? t("Settings") : route.view === 'backup' ? t("Backup and restore") : selectedSite?.name || t("Details")}</strong></div><div className="global-search"><Search size={17} /><input aria-label={t("Search archived pages")} placeholder={t("Search the archive…")} value={search} onChange={event => setSearch(event.target.value)} />{search && <button className="icon-button" aria-label={t("Clear search")} onClick={() => setSearch('')}><X size={15} /></button>}{results !== null && <div className="search-results">{results.length ? results.map(result => <button key={result.id} onClick={() => { go('page', result.id); setSearch(''); }}><span>{result.title || urlPath(result.url)}</span><small>{result.siteName} · {host(result.url)}</small></button>) : <p>{t("No pages found.")}</p>}</div>}</div><div className={`worker-status ${dashboard?.worker.available ? '' : 'offline'}`}><span />{dashboard?.worker.available ? dashboard?.stats.running ? t("Capturing pages") : activeJobs ? t("Checks queued") : sites.some(site => !site.paused) ? t("Monitoring active") : t("Archive ready") : t("Captures unavailable")}</div></header>
    <main className="main-content">{error && <div className="notice error" role="alert"><span>{systemMessage(error)}</span><button className="text-button" onClick={() => load()}>{t("Retry")}</button><button className="icon-button" aria-label={t("Dismiss error")} onClick={() => setError('')}><X size={17} /></button></div>}{dashboard && !dashboard.worker.available && <div className="notice amber"><Clock3 size={18} /><span>{systemMessage(dashboard.worker.message || t("The capture service is not running. Check the app status in Umbrel."))}</span></div>}{dashboard && !dashboard.worker.schedulerEnabled && <div className="notice amber">{t("Automatic checks are disabled. Use “Check and download now” for a manual visit.")}</div>}{dashboard && dashboard.storage.freeBytes < dashboard.storage.minFreeBytes && <div className="notice amber"><FolderArchive size={18} /><span>{t("Free disk space is below the safety threshold. New captures are paused; existing versions remain available.")}</span></div>}
    {loading ? <Spinner label={t("Loading the archive")} /> : route.view === 'overview' && dashboard ? <Overview data={dashboard} sites={sites} addSite={() => setEditingSite('new')} /> : route.view === 'inbox' ? <InboxView sites={sites} /> : route.view === 'library' ? <LibraryView sites={sites} /> : route.view === 'settings' ? <SettingsView /> : route.view === 'backup' ? <BackupView restored={() => load(true)} /> : route.view === 'sites' ? <SitesView sites={sites} addSite={() => setEditingSite('new')} remove={setDeletingSite} perform={perform} jobs={dashboard?.queue || []} /> : route.view === 'site' && detail && !('page' in detail) ? <SiteView detail={detail} edit={() => setEditingSite(detail.site)} remove={() => setDeletingSite(detail.site)} perform={perform} refresh={() => load(true)} notify={notify} /> : route.view === 'page' && detail && 'page' in detail ? <PageView detail={detail} versionId={route.versionId} perform={perform} refresh={() => load(true)} /> : <Empty icon={<Globe2 size={30} />} title={t("Page unavailable")} action={<a className="button secondary" href="#/overview">{t("Back to overview")}</a>}>{t("The requested content is not available in the archive.")}</Empty>}
    </main><footer className="workspace-footer"><span><LockKeyhole size={13} /> {t(" Captures stay in your local archive")}</span><SecureLink href="/api/source" download>{t("Source code · AGPL-3.0")}</SecureLink></footer></div>
    {deletingSite && <DeleteSiteModal site={deletingSite} close={() => setDeletingSite(null)} deleted={deleted} />}{editingSite && <SiteModal site={editingSite === 'new' ? undefined : editingSite} close={() => setEditingSite(null)} saved={async () => { setEditingSite(null); notify(editingSite === 'new' ? t("Site added. The first capture is queued.") : t("Site settings saved.")); await load(true); }} />}{toast && <div className="toast" role="status"><Check size={18} /><span>{systemMessage(toast)}</span><button className="icon-button" aria-label={t("Dismiss notification")} onClick={() => setToast('')}><X size={16} /></button></div>}
  </div>;
}

function Overview({ data, sites, addSite }: { data: Dashboard; sites: Site[]; addSite: () => void }) {
  return <><div className="page-heading"><div><span className="eyebrow">{t("EVERY CHANGE, IN ITS PLACE")}</span><h1>{t("The web changes. Keep the story.")}</h1><p>{t("The history of your sites and competitors, collected day by day.")}</p></div><button className="button primary" onClick={addSite}><Plus size={18} /> {t(" Add site")}</button></div><div className="stats-grid">{([{ label: t("Monitored sites"), value: data.stats.sites, icon: <Globe2 size={20} />, sub: t("{p0} yours · {p1} competitors", { p0: sites.filter(site => site.kind === 'own').length, p1: sites.filter(site => site.kind === 'competitor').length }) }, { label: t("Discovered pages"), value: data.stats.pages, icon: <FileText size={20} />, sub: t("Landing pages and pages in your archive") }, { label: t("Saved versions"), value: data.stats.versions, icon: <History size={20} />, sub: t("Copies saved over time") }, { label: t("Archive storage"), value: bytes(data.stats.bytes), icon: <FolderArchive size={20} />, sub: t("{p0} free on disk", { p0: bytes(data.storage.freeBytes) }) }]).map(stat => <div className="stat-card" key={stat.label}><div><span>{stat.label}</span>{stat.icon}</div><strong>{stat.value}</strong><small>{stat.sub}</small></div>)}</div>
    {!sites.length ? <section className="welcome-panel"><div className="welcome-illustration"><div className="illustration-page back"><span /><span /><span /></div><div className="illustration-page front"><div /><span /><span /><span /><History size={34} /></div></div><div><span className="eyebrow">{t("THE FIRST PAGE OF YOUR HISTORY")}</span><h2>{t("Which site shall we start with?")}</h2><p>{t("Add a domain or landing page. We will save a first copy and check for changes at the interval you choose.")}</p><button className="button primary" onClick={addSite}><Plus size={18} /> {t(" Add your first site")}</button></div></section> : <div className="overview-columns"><section className="panel"><div className="panel-heading"><div><h2>{t("Sites you follow")}</h2><p>{t("A starting point for every story.")}</p></div><a className="text-button" href="#/sites">{t("View all ")}<ArrowRight size={16} /></a></div><div className="site-list">{sites.slice(0, 5).map(site => <SiteRow key={site.id} site={site} />)}</div></section><section className="panel activity-panel"><div className="panel-heading"><div><h2>{t("Recent activity")}</h2><p>{t("New pages, versions and checks.")}</p></div><span className="small-icon"><History size={19} /></span></div><EventList events={data.events.slice(0, 8)} /></section></div>}
    <section className="panel acquisition-health" aria-label={t("Capture engine and temporary storage status")}><div><h2>{t("Capture engine")}</h2><p>App {data.version} {t(" · Engine ")}{data.worker.version || t("version unavailable")}</p>{data.worker.compatible === false ? <p className="engine-mismatch" role="status">{t("The app and engine are incompatible. Update the engine in Umbrel to version ")}{data.worker.expectedVersion || data.version}{t("; your saved copies remain available.")}</p> : <p>{data.worker.available ? t("Engine ready for captures.") : systemMessage(data.worker.message) || t("Engine temporarily unavailable.")}</p>}</div>{data.diagnosticsStatus && <div><h2>{t("Temporary samples")}</h2><p><strong>{bytes(data.diagnosticsStatus.bytes)}</strong> {t(" of ")}{bytes(data.diagnosticsStatus.maxBytes)} · {data.diagnosticsStatus.count} {t(" samples")}</p><p>{t("Ordinary samples expire within ")}{data.diagnosticsStatus.retentionHours} {t(" hours. New evidence stays in the archive.")}</p>{data.diagnosticsStatus.bytes >= data.diagnosticsStatus.maxBytes && <p className="engine-mismatch">{t("Temporary storage is full: further anomaly samples may not be saved.")}</p>}</div>}</section>
    {!!data.queue.length && <section className="panel queue-panel"><div className="panel-heading"><div><h2>{t("Capture queue")}</h2><p>{data.stats.running} {t(" running · ")}{data.stats.queued} {t(" queued")}</p></div><LoaderCircle size={19} className={data.stats.running ? 'spin' : ''} /></div><div className="queue-list">{data.queue.slice(0, 8).map(job => <div key={job.id}><span className={`queue-dot ${job.status === 'running' ? 'running' : ''}`} /><div><strong>{job.siteName || host(job.url)}</strong><small title={job.url}>{job.url}</small></div><span className="muted job-kind">{statusLabel(job.kind)}</span><Badge tone={job.status === 'running' ? 'green' : 'neutral'}>{statusLabel(job.status)}</Badge></div>)}</div></section>}
    <section className="insight-strip"><div className="insight-icon"><Sparkles size={21} /></div><p><strong>{t("A landing page can disappear. Your copy stays.")}</strong><span>{t("Add addresses found in ads and newsletters too: pages without public links may not be discovered by the scan.")}</span></p></section></>;
}

function SiteRow({ site }: { site: Site }) { return <a className="site-row" href={`#/site/${site.id}`}><div className={`site-avatar ${site.kind === 'own' ? 'own' : ''}`}>{site.name.slice(0, 1).toUpperCase()}</div><div className="site-row-name"><strong>{site.name}</strong><span>{host(site.url)}</span></div><div className="site-row-count"><strong>{site.pageCount || 0} {t(" pages")}</strong><span>{site.versionCount || 0} {t(" versions")}</span></div><Badge tone={site.paused ? 'neutral' : 'green'}>{site.paused ? t("Paused") : t("Every {p0} h", { p0: site.intervalHours })}</Badge><ChevronRight size={17} className="muted" /></a>; }

function EventList({ events }: { events: Event[] }) { return events.length ? <div className="event-list">{events.map(event => <div className="event-row" key={event.id}><div className={`event-marker ${isErrorStatus(event.kind) ? 'warning' : ''}`}>{isErrorStatus(event.kind) ? <Clock3 size={14} /> : event.kind === 'discovered' || event.kind === 'new' ? <Plus size={14} /> : <History size={14} />}</div><div><div className="event-top"><strong>{event.siteName || host(event.url)}</strong><time>{date(event.createdAt, true)}</time></div><p>{systemMessage(event.message || statusLabel(event.kind))}</p>{event.url && <small title={event.url}>{urlPath(event.url)}</small>}</div></div>)}</div> : <div className="activity-empty"><Clock3 size={26} /><p>{t("The story starts with the first check.")}</p><span>{t("Activity from your sites will appear here.")}</span></div>; }

function SitesView({ sites, addSite, remove, perform, jobs }: { sites: Site[]; addSite: () => void; remove: (site: Site) => void; perform: Action; jobs: Job[] }) {
  const [filter, setFilter] = useState('all'); const [query, setQuery] = useState(''); const filtered = sites.filter(site => (filter === 'all' || site.kind === filter) && `${site.name} ${site.url}`.toLowerCase().includes(query.toLowerCase()));
  return <><div className="page-heading"><div><span className="eyebrow">{t("YOUR OBSERVATORY")}</span><h1>{t("Monitored sites")}</h1><p>{t("Follow your projects and see how competitors evolve.")}</p></div><button className="button primary" onClick={addSite}><Plus size={18} /> {t(" Add site")}</button></div><div className="list-toolbar"><div className="tabs">{[{ key: 'all', label: t("All sites") }, { key: 'own', label: t("My sites") }, { key: 'competitor', label: 'Competitor' }].map(tab => <button key={tab.key} className={filter === tab.key ? 'selected' : ''} onClick={() => setFilter(tab.key)}>{tab.label} <span>{sites.filter(site => tab.key === 'all' || site.kind === tab.key).length}</span></button>)}</div><div className="input-search"><Search size={16} /><input aria-label={t("Filter sites")} placeholder={t("Filter by name or domain")} value={query} onChange={event => setQuery(event.target.value)} /></div></div>{filtered.length ? <div className="site-cards">{filtered.map(site => <article className="site-card" key={site.id}><a className="site-card-link" href={`#/site/${site.id}`}><div className="site-card-top"><div className={`site-avatar ${site.kind === 'own' ? 'own' : ''}`}>{site.name.slice(0, 1).toUpperCase()}</div><Badge>{site.kind === 'own' ? t("My site") : 'Competitor'}</Badge><ArrowUpRight size={19} /></div><h2>{site.name}</h2><p className="domain">{host(site.url)}</p><div className="site-card-numbers"><div><strong>{site.pageCount || 0}</strong><span>{t("Pages")}</span></div><div><strong>{site.versionCount || 0}</strong><span>{t("Versions")}</span></div></div><div className="site-card-footer"><span><span className={`site-dot ${site.paused ? 'paused' : ''}`} />{site.paused ? t("Monitoring paused") : t("Check every {p0} h", { p0: site.intervalHours })}</span><small>{t("Last: ")}{date(site.lastCheckedAt, true)}</small></div></a><div className="site-card-actions"><ScanButton siteId={site.id} running={jobs.some(job => job.siteId === site.id && job.status === "running")} perform={perform} compact /><button className="button danger-outline compact" onClick={() => remove(site)} aria-label={t("Delete {p0}", { p0: site.name })}><Trash2 size={15} /> {t(" Delete")}</button></div></article>)}</div> : <div className="panel"><Empty icon={<Globe2 size={30} />} title={sites.length ? t("No matching sites") : t("Your archive starts with an address")} action={!sites.length && <button className="button primary" onClick={addSite}><Plus size={17} /> {t(" Add site")}</button>}>{sites.length ? t("Try changing the filter or search.") : t("Add your first site to start keeping its history.")}</Empty></div>}</>;
}

function SiteView({ detail, edit, remove, perform, refresh, notify }: { detail: SiteDetail; edit: () => void; remove: () => void; perform: (fn: () => Promise<unknown>, message: string) => Promise<void>; refresh: () => Promise<void>; notify: (message: string) => void }) {
  const { site, pages } = detail; const [addingPage, setAddingPage] = useState(false); const [resetting, setResetting] = useState(false);
  return <><a className="back-link" href="#/sites"><ArrowLeft size={15} /> {t(" All sites")}</a><div className="page-heading site-heading"><div><div className="heading-badges"><Badge tone="green">{site.kind === 'own' ? t("My site") : 'Competitor'}</Badge>{site.paused && <Badge>{t("Paused")}</Badge>}</div><h1>{site.name}</h1><a className="external-link" href={site.url} target="_blank" rel="noreferrer">{site.url}<ExternalLink size={13} /></a></div><div className="button-group"><SecureLink className="button secondary" href={`/api/sites/${site.id}/export`} download><ArrowDownToLine size={17} /> {t(" Export offline site")}</SecureLink><button className="button secondary" onClick={edit}><Settings2 size={17} /> {t(" Settings")}</button><ScanButton siteId={site.id} running={detail.jobs.some(job => job.status === "running")} perform={perform} /><button className="button danger-outline" onClick={() => setResetting(true)}><RefreshCw size={17} /> {t(" Clear copies and scan again")}</button><button className="button danger-outline" onClick={remove}><Trash2 size={17} /> {t(" Delete site")}</button></div></div><div className="site-summary"><span><FileText size={17} /><strong>{pages.length}</strong> {t(" pages")}</span><span><History size={17} /><strong>{site.versionCount || 0}</strong> {t(" versions")}</span><span><Clock3 size={17} /> {t(" Every ")}{site.intervalHours} {t(" hours")}</span><span className="next-check">{site.paused ? t("Schedule paused") : t("Next check: {p0}", { p0: date(site.nextCheckAt, true) })}</span></div><AcquisitionStatus jobs={detail.jobs} paused={site.paused} error={detail.events.find(event => isErrorStatus(event.kind))?.message} /><div className="discovery-summary"><strong>{t("New landing discovery every ")}{site.discoveryIntervalHours} {t(" hours")}</strong><span>{t("Last discovery: ")}{date(site.lastDiscoveryAt, true)}</span><span>{site.paused ? t("Automatic discovery paused") : t("Next discovery: {p0}", { p0: date(site.nextDiscoveryAt, true) })}</span><small>{t("A manual site check also discovers new addresses.")}</small></div><LandingLifecycle pages={pages} maxPages={site.maxPages} date={date} statusLabel={statusLabel} add={() => setAddingPage(true)} /><div className="site-lower-grid"><section className="panel"><div className="panel-heading"><div><h2>{t("Site activity")}</h2><p>{t("The history of checks and discoveries.")}</p></div></div><EventList events={detail.events.slice(0, 8)} /></section><section className="panel site-guidance"><Link2 size={24} /><h2>{t("Found a new landing page?")}</h2><p>{t("Addresses found only in ads, emails or private areas can be missed by automatic discovery. Add them here to track their history.")}</p><button className="button secondary" onClick={() => setAddingPage(true)}><Plus size={16} /> {t(" Add an address")}</button><div className="site-guidance-note"><ShieldCheck size={17} /><span>{t("Earlier versions remain available even when a page changes or disappears.")}</span></div></section></div>{resetting && <ResetSiteModal site={site} close={() => setResetting(false)} done={async message => { setResetting(false); notify(message); await refresh(); }} />}{addingPage && <AddPageModal site={site} close={() => setAddingPage(false)} saved={async () => { setAddingPage(false); notify(t("Page added. The first capture is queued.")); await refresh(); }} />}</>;
}

function PageView({ detail, perform, refresh, versionId }: { versionId?: string; detail: PageDetail; refresh: () => Promise<void>; perform: (fn: () => Promise<unknown>, message: string) => Promise<void> }) {
  const { page, site } = detail;
  const versions = [...detail.versions].sort((a, b) => b.capturedAt.localeCompare(a.capturedAt) || b.id.localeCompare(a.id));
  const defaultId = page.latestVersionId || detail.referenceVersionId || page.referenceVersionId || versions[0]?.id || '';
  const [view, setView] = useState<'offline' | 'screenshot'>('offline');
  const [selectedId, setSelectedId] = useState(versionId || defaultId);
  const [selectedObservation, setSelectedObservation] = useState<Observation>();
  const [explicitSelection, setExplicitSelection] = useState(false);
  const [mode, setMode] = useState<'preview' | 'compare' | 'checks' | 'rules'>('preview');
  const [notes, setNotes] = useState(detail.notes || '');
  const [savingNotes, setSavingNotes] = useState(false);
  const [imageError, setImageError] = useState(false);
  const observations = useObservations(page.id, detail.checks, detail.historySummary?.checks);
  useEffect(() => { setSelectedId(versionId || defaultId); setSelectedObservation(undefined); setExplicitSelection(false); setMode('preview'); setNotes(detail.notes || ''); }, [page.id, versionId]);
  useEffect(() => { if (!versions.some(version => version.id === selectedId) && versions.length) { setSelectedId(defaultId); setSelectedObservation(undefined); } }, [versions, selectedId, defaultId]);
  useEffect(() => setImageError(false), [selectedId]);
  const selected = versions.find(version => version.id === selectedId) || versions.find(version => version.id === defaultId) || versions[0];
  // A returned variant may reuse old files. Keep the accepted visit time for links in the offline page.
  const latestVisit = !versionId && !explicitSelection && selected?.id === page.latestVersionId ? observations.checks.find(check => check.versionId === selected.id && ['first', 'change', 'returned', 'baseline'].includes(check.evidence?.kind || '')) : undefined;
  const activeObservation = selectedObservation || latestVisit;
  function select(id: string, check?: Observation) { setSelectedId(id); setSelectedObservation(check); setExplicitSelection(true); setMode('preview'); }
  return <>
    <a className="back-link" href={`#/site/${site.id}`}><ArrowLeft size={15} /> {site.name}</a>
    <div className="page-heading detail-heading"><div><span className="eyebrow">{t("PAGE HISTORY")}</span><h1>{page.title || urlPath(page.url)}</h1><a className="external-link" href={page.url} target="_blank" rel="noreferrer">{page.url}<ExternalLink size={13} /></a></div><ScanButton siteId={site.id} pageId={page.id} running={detail.jobs.some(job => job.status === 'running')} perform={perform} /></div>
    <AcquisitionStatus jobs={detail.jobs} paused={site.paused} error={detail.checks[0] && isErrorStatus(detail.checks[0].status) ? detail.checks[0].message : undefined} />
    {detail.historySummary && <div className="history-overview" aria-label={t("History summary")}><span><strong>{detail.historySummary.confirmed}</strong> {t(" confirmed")}</span><span><strong>{detail.historySummary.observed}</strong> {t(" evidence to review")}</span><span><strong>{detail.historySummary.legacy}</strong> {t(" earlier copies")}</span><span><strong>{detail.historySummary.checks}</strong> {t(" recorded checks")}</span></div>}
    {page.pendingConfirmation && <div className="notice amber"><Clock3 size={18} /><span>{t("A difference observed on ")}{date(page.pendingConfirmation.firstSeenAt)} {t(" still needs verification. The previous reference remains available. ")}{site.paused ? t("You can repeat the check manually.") : page.pendingConfirmation.retries >= 2 ? t("The limit for closely spaced attempts has been reached; monitoring continues at the site's regular interval.") : t("A confirmation check is scheduled.")}</span></div>}
    <div className="page-detail-tabs"><div className="tabs"><button className={mode === 'preview' ? 'selected' : ''} aria-pressed={mode === 'preview'} onClick={() => setMode('preview')}><Monitor size={16} /> {t(" Versions ")}<span>{versions.length}</span></button><button className={mode === 'compare' ? 'selected' : ''} aria-pressed={mode === 'compare'} disabled={versions.length < 2} title={versions.length < 2 ? t("At least two versions are needed for comparison") : undefined} onClick={() => setMode('compare')}><History size={16} /> {t(" Compare")}</button><button className={mode === 'checks' ? 'selected' : ''} aria-pressed={mode === 'checks'} onClick={() => setMode('checks')}><Clock3 size={16} /> {t(" Checks ")}<span>{detail.historySummary?.checks ?? detail.checks.length}</span></button><button className={mode === 'rules' ? 'selected' : ''} aria-pressed={mode === 'rules'} onClick={() => setMode('rules')}><Settings2 size={16} /> {t(" Monitoring areas")}</button></div><span className="muted">{t("Last check: ")}{date(page.lastCheckedAt, true)}</span></div>
    {mode === 'preview' && (selected ? <div className="timeline-layout">
      <TimelineView key={page.id} versions={versions} selectedId={selected.id} selectedAt={activeObservation?.createdAt} referenceVersionId={detail.referenceVersionId || page.referenceVersionId} summary={detail.historySummary} observations={observations} select={select} date={date} bytes={bytes} />
      <section className="panel capture-panel"><div className="capture-toolbar"><div><span className="capture-browser-dots"><i /><i /><i /></span><span title={selected.finalUrl}>{host(selected.finalUrl || page.url)}{urlPath(selected.finalUrl || page.url)}</span></div><div className="tabs capture-view-tabs"><button className={view === 'offline' ? 'selected' : ''} aria-pressed={view === 'offline'} onClick={() => setView('offline')}><Globe2 size={15} /> {t(" Offline page")}</button><button className={view === 'screenshot' ? 'selected' : ''} aria-pressed={view === 'screenshot'} onClick={() => setView('screenshot')}><Monitor size={15} /> Screenshot</button></div></div>
        <QualitySummary version={selected} reference={selected.id === (detail.referenceVersionId || page.referenceVersionId)} observation={activeObservation} date={date} />
        {view === 'offline' ? <OfflineView key={`${selected.id}:${activeObservation?.createdAt || ''}`} version={selected} at={activeObservation?.createdAt} date={date} /> : <><div className="capture-meta"><span><Monitor size={15} /> {t(" Desktop view")}</span><time>{date(selected.capturedAt)}</time><Badge tone={selected.statusCode >= 400 ? 'amber' : 'green'}>{selected.statusCode ? `HTTP ${selected.statusCode}` : t("Captured")}</Badge></div><div className="screenshot-view">{imageError || !selected.screenshotUrl ? <Empty icon={<Monitor size={28} />} title={t("Preview unavailable")}>{t("You can browse the offline page or download the HTML copy.")}</Empty> : <SecureLink href={selected.screenshotUrl} target="_blank" rel="noreferrer" title={t("Open full screenshot")}><SecureImage key={selected.id} src={selected.screenshotUrl} alt={t("Screenshot of {p0}, captured on {p1}", { p0: page.title || host(page.url), p1: date(selected.capturedAt) })} onError={() => setImageError(true)} /></SecureLink>}</div><div className="capture-footer"><SecureLink className="text-button" href={selected.htmlUrl} download><ArrowDownToLine size={15} /> {t(" Download HTML")}</SecureLink><ShieldCheck size={14} /> {t(" Screenshot of the archived page.")}</div></>}
      </section>
    </div> : <section className="panel"><Empty icon={<History size={31} />} title={detail.checks.some(check => isErrorStatus(check.status)) ? t("The first capture failed") : t("No archived versions")} action={<ScanButton siteId={site.id} pageId={page.id} running={detail.jobs.some(job => job.status === 'running')} perform={perform} />}>{t("Once the capture completes, you can explore the page and its versions here.")}</Empty></section>)}
    {mode === 'preview' && selected && <VersionAnnotation key={selected.id} versionId={selected.id} capturedAt={date(selected.capturedAt)} />}
    {mode === 'rules' && <RuleEditor key={page.id} pageId={page.id} versions={versions} initial={{ ignoreRules: page.ignoreRules, importantRules: page.importantRules }} inherited={site.ignoreSelectors} saved={refresh} />}
    {mode === 'compare' && <CompareView versions={versions} selectedId={selected?.id} date={date} />}
    {mode === 'checks' && <section className="panel checks-panel"><div className="panel-heading"><div><h2>{t("All observations")}</h2><p>{t("Checks, anomalies and returns to earlier variants, in the order they happened.")}</p></div></div><ObservationList observations={observations} versions={versions} date={date} select={select} total={detail.historySummary?.checks} /></section>}
    {(mode === 'preview' || mode === 'checks') && <><DiagnosticsPanel diagnostics={detail.diagnostics || []} date={date} bytes={bytes} /><ArchiveReview key={page.id} pageId={page.id} date={date} bytes={bytes} refresh={refresh} /></>}
    <section className="panel notes-panel"><div className="notes-heading"><MessageSquare size={20} /><div><h2>{t("Your observations")}</h2><p>{t("Promises, offers, experiments: keep the context alongside the page.")}</p></div></div><textarea aria-label={t("Page notes")} rows={3} placeholder={t("Write what you noticed on this landing page…")} value={notes} onChange={event => setNotes(event.target.value)} /><div><small>{t("Visible changes can suggest hypotheses; they do not reveal conversion results.")}</small><button className="button secondary compact" disabled={savingNotes || notes === (detail.notes || '')} onClick={async () => { setSavingNotes(true); await perform(() => api(`/api/pages/${page.id}`, { method: 'PATCH', body: JSON.stringify({ notes }) }), t("Notes saved.")); setSavingNotes(false); }}>{savingNotes ? <LoaderCircle size={15} className="spin" /> : <Check size={15} />} {t(" Save page notes")}</button></div></section>
  </>;
}


function Modal({ title, subtitle, close, children }: { title: string; subtitle?: string; close: () => void; children: ReactNode }) {
  const dialog = useRef<HTMLDivElement>(null); const closeRef = useRef(close); closeRef.current = close;
  useEffect(() => { const previous = document.activeElement as HTMLElement; const previousOverflow = document.body.style.overflow; document.body.style.overflow = 'hidden'; const timer = setTimeout(() => dialog.current?.querySelector<HTMLElement>('input,button')?.focus(), 10); const keydown = (event: KeyboardEvent) => { if (event.key === 'Escape') closeRef.current(); if (event.key === 'Tab') { const controls = dialog.current?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href]'); if (!controls?.length) return; const first = controls[0], last = controls[controls.length - 1]; if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); } else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); } } }; document.addEventListener('keydown', keydown); return () => { clearTimeout(timer); document.body.style.overflow = previousOverflow; document.removeEventListener('keydown', keydown); previous?.focus(); }; }, []);
  return <div className="modal-overlay" onMouseDown={event => { if (event.target === event.currentTarget) close(); }}><div className="modal" ref={dialog} role="dialog" aria-modal="true" aria-labelledby="modal-title"><div className="modal-heading"><div><h2 id="modal-title">{title}</h2>{subtitle && <p>{subtitle}</p>}</div><button className="icon-button" onClick={close} aria-label={t("Close window")}><X size={21} /></button></div>{children}</div></div>;
}

function SiteModal({ site, close, saved }: { site?: Site; close: () => void; saved: () => Promise<void> }) {
  const [name, setName] = useState(site?.name || ''); const [url, setUrl] = useState(site?.url || ''); const [kind, setKind] = useState(site?.kind || 'competitor'); const [intervalHours, setIntervalHours] = useState(site?.intervalHours || 6); const [maxPages, setMaxPages] = useState(site?.maxPages || 30); const [discoveryIntervalHours, setDiscoveryIntervalHours] = useState(site?.discoveryIntervalHours || 24); const [includePaths, setIncludePaths] = useState((site?.includePaths || []).join('\n')); const [excludePaths, setExcludePaths] = useState((site?.excludePaths || []).join('\n')); const [includeSubdomains, setIncludeSubdomains] = useState(site?.includeSubdomains || false); const [paused, setPaused] = useState(site?.paused || false); const [selectors, setSelectors] = useState((site?.ignoreSelectors || []).join('\n')); const [notes, setNotes] = useState(site?.notes || ''); const [advanced, setAdvanced] = useState(false); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  async function submit(event: FormEvent) { event.preventDefault(); setBusy(true); setError(''); try { const body = { name: name.trim(), url: url.trim(), kind, intervalHours, discoveryIntervalHours, includePaths: includePaths.split('\n').map(v => v.trim()).filter(Boolean), excludePaths: excludePaths.split('\n').map(v => v.trim()).filter(Boolean), maxPages, includeSubdomains, ignoreSelectors: selectors.split('\n').map(value => value.trim()).filter(Boolean), ...(site ? { paused, notes } : {}) }; await api(site ? `/api/sites/${site.id}` : '/api/sites', { method: site ? 'PATCH' : 'POST', body: JSON.stringify(body) }); await saved(); } catch (error) { setError((error as Error).message); } finally { setBusy(false); } }
  return <Modal title={site ? t("Site settings") : t("Add a site")} subtitle={site ? t("Choose how to follow its evolution.") : t("An address today, a history to explore tomorrow.")} close={() => { if (!busy) close(); }}><form onSubmit={submit}><div className="modal-body"><label>{t("Site name")}<input required maxLength={120} placeholder={t("How you want it to appear in the archive")} value={name} onChange={event => setName(event.target.value)} /></label><label>{t("Starting address")}<input type="url" required disabled={!!site} placeholder="https://…" value={url} onChange={event => setUrl(event.target.value)} /><small>{t("Start from a domain or a specific landing page.")}</small></label><fieldset className="kind-picker"><legend>{t("This site is")}</legend><label className={kind === 'own' ? 'selected' : ''}><input type="radio" name="site-kind" checked={kind === 'own'} onChange={() => setKind('own')} /><Globe2 size={18} /><span>{t("One of my sites")}</span></label><label className={kind === 'competitor' ? 'selected' : ''}><input type="radio" name="site-kind" checked={kind === 'competitor'} onChange={() => setKind('competitor')} /><Search size={18} /><span>{t("A competitor")}</span></label></fieldset><div className="form-columns"><label>{t("Check pages every")}<div className="input-suffix"><input type="number" required min={1} max={8760} value={intervalHours} onChange={event => setIntervalHours(Number(event.target.value))} /><span>{t("hours")}</span></div></label><label>{t("Page limit per site")}<input type="number" required min={1} max={500} value={maxPages} onChange={event => setMaxPages(Number(event.target.value))} /></label></div><label>{t("Discover new landing pages every")}<div className="input-suffix"><input type="number" required min={1} max={8760} value={discoveryIntervalHours} onChange={event => setDiscoveryIntervalHours(Number(event.target.value))} /><span>{t("hours")}</span></div></label><div className="form-info"><Clock3 size={18} /><span>{t("Discovery of new addresses and checks of known pages have independent schedules. Jobs run one at a time.")}</span></div><label className="checkbox-label"><input type="checkbox" checked={includeSubdomains} onChange={event => setIncludeSubdomains(event.target.checked)} /><span>{t("Include subdomains")}<small>{t("Find linked public pages on subdomains of the same site.")}</small></span></label>{site && <label className="checkbox-label"><input type="checkbox" checked={paused} onChange={event => setPaused(event.target.checked)} /><span>{t("Pause monitoring")}<small>{t("Previously archived copies remain available.")}</small></span></label>}<button type="button" className="advanced-toggle" onClick={() => setAdvanced(!advanced)}><Settings2 size={15} /> {t(" Advanced options ")}<ChevronRight className={advanced ? 'rotate' : ''} size={15} /></button>{advanced && <div className="advanced-fields"><label>{t("Discover landing pages under these paths")}<textarea rows={2} placeholder="/offers\n/webinar" value={includePaths} onChange={event => setIncludePaths(event.target.value)} /><small>{t("One path per line. Leave empty to search the whole site.")}</small></label><label>{t("Exclude these paths from discovery")}<textarea rows={2} placeholder="/privacy\n/blog" value={excludePaths} onChange={event => setExcludePaths(event.target.value)} /><small>{t("Applies to new addresses. Archived pages and manually added URLs are still checked.")}</small></label><label>{t("Elements to ignore in comparisons")}<textarea rows={3} placeholder={t("One CSS selector per line")} value={selectors} onChange={event => setSelectors(event.target.value)} /><small>{t("For example, counters or changing widgets. Elements are excluded from comparisons; new HTML copies and screenshots stay complete. You can also select areas by clicking in the page details.")}</small></label>{site && <label>{t("Site notes")}<textarea rows={3} value={notes} onChange={event => setNotes(event.target.value)} /></label>}</div>}{error && <div className="notice error" role="alert">{systemMessage(error)}</div>}</div><div className="modal-footer"><button type="button" className="button secondary" disabled={busy} onClick={close}>{t("Cancel")}</button><button className="button primary" disabled={busy}>{busy ? <LoaderCircle size={17} className="spin" /> : site ? <Check size={17} /> : <Plus size={17} />}{site ? t("Save settings") : t("Add and capture")}</button></div></form></Modal>;
}

function AddPageModal({ site, close, saved }: { site: Site; close: () => void; saved: () => Promise<void> }) {
  const [url, setUrl] = useState(''); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  return <Modal title={t("Add a page")} subtitle={t("The new page will belong to {p0}.", { p0: site.name })} close={() => { if (!busy) close(); }}><form onSubmit={async event => { event.preventDefault(); setBusy(true); setError(''); try { await post(`/api/sites/${site.id}/pages`, { url: url.trim() }); await saved(); } catch (error) { setError((error as Error).message); } finally { setBusy(false); } }}><div className="modal-body"><label>{t("Landing page address")}<input type="url" required placeholder="https://…" value={url} onChange={event => setUrl(event.target.value)} /><small>{t("Paste the full address found on a website, in an ad or in a newsletter.")}</small></label>{error && <div className="notice error" role="alert">{systemMessage(error)}</div>}</div><div className="modal-footer"><button type="button" className="button secondary" disabled={busy} onClick={close}>{t("Cancel")}</button><button className="button primary" disabled={busy}>{busy ? <LoaderCircle size={17} className="spin" /> : <Plus size={17} />} {t(" Add page")}</button></div></form></Modal>;
}
